def gen(rng):
    def fmt(segs, k):
        return '%d %d\n%s' % (len(segs), k, '\n'.join('%d %d %d' % s for s in segs))

    def small(m, maxgap, maxlen, k):
        pos = rng.randint(1, 3)
        segs = []
        for _ in range(m):
            pos += rng.randint(0, maxgap)
            ln = rng.randint(1, maxlen)
            segs.append((pos, pos + ln - 1, rng.randint(1, 9)))
            pos += ln
        rng.shuffle(segs)
        return fmt(segs, k)

    def big(n, k, span, cmax):
        pts = sorted(rng.sample(range(1, span + 1), 2 * n))
        segs = [(pts[2 * i], pts[2 * i + 1], rng.randint(1, cmax)) for i in range(n)]
        rng.shuffle(segs)
        return fmt(segs, k)

    tests = [fmt([(1, 1, 1)], 1), fmt([(5, 9, 3)], 2), fmt([(5, 9, 3)], 100), fmt([(1, 3, 2), (4, 6, 5)], 4),
             fmt([(1, 3, 2), (5, 6, 4), (8, 8, 5)], 4), fmt([(1, 2, 3), (1000, 1000, 7)], 100),
             fmt([(3, 100, 10)], 5), fmt([(1, 1, 5), (3, 3, 5), (5, 5, 5)], 3)]
    for _ in range(26):
        tests.append(small(rng.randint(1, 6), rng.choice([0, 1, 3, 6]), rng.randint(1, 5), rng.randint(1, 30)))
    tests.append(big(50000, 10**9, 10**9, 1000))
    tests.append(big(50000, 3 * 10**6, 10**9, 1000))
    tests.append(big(50000, 10**5, 4 * 10**5 + 50000, 1000))
    tests.append(big(50000, 1, 10**9, 1000))
    tests.append(big(30000, 5 * 10**8, 10**9, 7))
    return tests
